components.css:
.ds-utility-card{font-family:"Source Han Sans SC", "Noto Sans CJK SC", "PingFang SC", "Microsoft YaHei", sans-serif;}.ds-utility-card{padding:16px;border-radius:20px;background:#fff;box-shadow:0 4px 14px -7px #26344a1c;}.ds-grid{--utility-columns:4;--utility-divider:#f1f4f8;display:grid;grid-template-columns:repeat(var(--utility-columns), minmax(0, 1fr));grid-auto-rows:1fr;gap:0;margin-top:16px;border:1px solid var(--utility-divider);border-radius:12px;overflow:hidden;}.ds-grid[data-columns="3"]{--utility-columns:3;}.ds-grid > .ds-grid-item{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;min-height:76px;gap:6px;padding:8px 4px;border:0;border-radius:0;background:transparent;box-shadow:none;font-size:13px;font-weight:500;line-height:20px;color:#4f5f76;text-align:center;overflow-wrap:anywhere;}.ds-grid:not([data-columns="3"]) > .ds-grid-item:not(:nth-child(4n)),
.ds-grid[data-columns="3"] > .ds-grid-item:not(:nth-child(3n)){border-inline-end:1px solid var(--utility-divider);}.ds-grid:not([data-columns="3"]) > .ds-grid-item:nth-child(n + 5),
.ds-grid[data-columns="3"] > .ds-grid-item:nth-child(n + 4){border-block-start:1px solid var(--utility-divider);}.ds-grid > .ds-grid-item:focus-visible{position:relative;z-index:1;outline-offset:-3px;}.ds-grid > .ds-grid-item:active{transform:none;}.ds-grid > .ds-grid-item:not([aria-disabled="true"]):active{background:#f4f7ff;}.ds-grid .ds-grid-icon{--tool-icon-light:#e5ebf4;--tool-icon-accent:#6583bc;position:relative;display:grid;place-items:center;flex:none;width:32px;height:32px;color:#7488a3;}.ds-grid .ds-grid-icon svg{width:24px;height:24px;stroke:none;}.ds-grid > .ds-grid-item > span:not(.ds-grid-icon){width:100%;}.ds-grid-detail{display:block;flex:none;min-height:18px;font-size:12px;font-weight:400;line-height:18px;color:#59677a;}.ds-grid-label{display:flex;flex:none;align-items:center;justify-content:center;min-height:40px;line-height:20px;white-space:normal;overflow-wrap:anywhere;}.ds-utility-card>h2{margin:0;font-size:16px;font-weight:650;line-height:24px;color:var(--ui-heading,#203858);}.ds-grid-item{font-family:inherit;cursor:pointer;}.ds-grid-item:focus-visible{outline:3px solid var(--brand-blue,#0032ff);}
